  need_help:     {hi:'मुझे मदद चाहिए', en:'I need help', bn:'আমার সাহায্য দরকার', ta:'எனக்கு உதவி வேண்டும்', te:'నాకు సహాయం కావాలి', mr:'मला मदत हवी', gu:'મને મદદ જોઈએ', es:'Necesito ayuda', fr:'J’ai besoin d’aide'},
