/** vitals payload key -> dictionary key. Shared so HealthView and the
    monitor strip can never drift apart on labels. */
export const VITAL_LABEL_KEY = {
  bp_sys: 'v_bp', bp_dia: 'v_bp_low', sugar: 'v_sugar',
  pulse: 'v_pulse', spo2: 'v_spo2',
}

export function tr(lang, key, vars) {
  const row = D[key]
  if (!row) return key
  let out = row[lang] || row.en || key
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      out = out.split('{' + k + '}').join(v == null ? '' : String(v))
    }
  }
  return out
}
